DELETE FROM dbo.DM2_FamilyMember WHERE UserName IN (SELECT UserName FROM #Del);
DELETE f FROM dbo.DM2_FamilyTeam f JOIN #DelTeam t ON t.TenantId = f.TenantId AND t.TeamId = f.FamilyTeamId;
