       (SELECT COUNT(*) FROM app.ClassMember) AS [ClassMembers],
       (SELECT COUNT(*) FROM app.AttendanceCheck) AS [Attendance],
       (SELECT COUNT(*) FROM dbo.DM2_MissionActivity) AS [MissionRows],
       (SELECT COUNT(*) FROM dbo.DM2_FamilyTeam) AS [Teams],
